    await appPrompt('Sao chép đường link Tab Nháp bên dưới để gửi cho bạn bè dùng thử:', shareUrl, {
      title: 'Chia Sẻ Link Tab Nháp',
      icon: 'share-2',
      readOnly: true,
      confirmText: 'Đã sao chép'
    });
